import os
import gc
import warnings
import string
import unicodedata
from copy import deepcopy
from collections import defaultdict

import numpy as np
import pandas as pd
import torch
from torch.utils.data import DataLoader, TensorDataset, SubsetRandomSampler
from torch.optim import AdamW
from torch.cuda.amp import autocast, GradScaler

from transformers import (
    AutoTokenizer,
    AutoConfig,
    AutoModelForQuestionAnswering,
    get_linear_schedule_with_warmup,
    logging as hf_logging,
)
from sklearn.model_selection import StratifiedKFold

warnings.filterwarnings("ignore")
os.environ["TOKENIZERS_PARALLELISM"] = "false"
hf_logging.set_verbosity_error()

SEED = 42
MAX_LEN = 512
STRIDE = 128
BATCH_SIZE = 16
EPOCHS = 3
LR_DEFAULT = 3e-5
MAX_ANSWER_LEN = 50
INFER_BATCH = 16
EMA_DECAY = 0.999

MODEL_CANDIDATES = [
    "deepset/xlm-roberta-large-squad2",
    "xlm-roberta-large",
]
TOKENIZER_MODEL = "xlm-roberta-large"

LR_BY_MODEL = {
    "deepset/xlm-roberta-large-squad2": 2e-5,
    "xlm-roberta-large": 3e-5,
}

PAD_ID = None
USE_TOKEN_TYPE = False


def set_seed(seed=SEED):
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def safe_mean(vals):
    vals = list(vals)
    if len(vals) == 0:
        return 0.0
    return float(np.mean(vals))


def jaccard_score(str1, str2):
    a = set(str(str1).lower().split())
    b = set(str(str2).lower().split())
    if len(a) == 0 and len(b) == 0:
        return 1.0
    return len(a & b) / len(a | b)


def _is_punct(ch):
    return unicodedata.category(ch).startswith("P") or ch in string.punctuation


def postprocess_answer(text):
    if text is None:
        return ""
    text = " ".join(str(text).split())
    s, e = 0, len(text)
    while s < e and _is_punct(text[s]):
        s += 1
    while e > s and _is_punct(text[e - 1]):
        e -= 1
    stripped = text[s:e]
    return stripped if stripped else text.strip()


def get_seq_ids(enc, i, tokenizer=None):
    if hasattr(enc, "sequence_ids"):
        try:
            seq = list(enc.sequence_ids(i))
            if any(x == 1 for x in seq):
                return seq
        except Exception:
            pass

    if hasattr(enc, "encodings") and enc.encodings is not None:
        try:
            seq = list(enc.encodings[i].sequence_ids())
            if any(x == 1 for x in seq):
                return seq
        except Exception:
            pass

    tt = enc.get("token_type_ids")
    if tt is not None:
        try:
            seq = list(tt[i])
            if any(x == 1 for x in seq):
                return seq
        except Exception:
            pass

    if tokenizer is not None and getattr(tokenizer, "sep_token_id", None) is not None:
        try:
            ids = list(enc["input_ids"][i])
            sep_id = tokenizer.sep_token_id
            first_sep = ids.index(sep_id)
            seq = [0] * len(ids)
            for j in range(first_sep + 1, len(ids)):
                seq[j] = 1
            if any(x == 1 for x in seq):
                return seq
        except Exception:
            pass

    return [0] * len(enc["input_ids"][i])


def build_train_windows(row, tokenizer):
    answer_text = str(row["answer_text"]).strip()
    if not answer_text:
        return []

    context = str(row["context"])
    question = str(row["question"])

    raw_start = row["answer_start"]
    start_char = int(raw_start) if pd.notna(raw_start) else -1

    if start_char >= 0 and context.startswith(answer_text, start_char):
        pass
    else:
        start_char = context.find(answer_text)
        if start_char == -1:
            start_char = context.lower().find(answer_text.lower())
        if start_char == -1:
            return []

    end_char = start_char + len(answer_text)

    encoded = tokenizer(
        question,
        context,
        max_length=MAX_LEN,
        stride=STRIDE,
        truncation="only_second",
        return_overflowing_tokens=True,
        return_offsets_mapping=True,
    )

    windows = []
    for i in range(len(encoded["input_ids"])):
        input_ids = encoded["input_ids"][i]
        offsets = encoded["offset_mapping"][i]
        seq_ids = get_seq_ids(encoded, i, tokenizer)

        start_tok = None
        end_tok = None

        for j, sid in enumerate(seq_ids):
            if sid != 1:
                continue
            s, e = offsets[j]
            if s == 0 and e == 0:
                continue
            if s <= start_char < e:
                start_tok = j
            if s < end_char <= e:
                end_tok = j

        if start_tok is None or end_tok is None or start_tok > end_tok:
            continue

        pad_len = MAX_LEN - len(input_ids)
        if pad_len < 0:
            continue

        attention_mask = [1] * len(input_ids) + [0] * pad_len
        input_ids = input_ids + [PAD_ID] * pad_len

        tt = encoded.get("token_type_ids")
        if tt is not None:
            token_type_ids = tt[i] + [0] * pad_len
        else:
            token_type_ids = [0] * len(input_ids)

        windows.append((input_ids, attention_mask, token_type_ids, start_tok, end_tok))

    return windows


def build_inference_windows(question, context, tokenizer):
    encoded = tokenizer(
        question,
        context,
        max_length=MAX_LEN,
        stride=STRIDE,
        truncation="only_second",
        return_overflowing_tokens=True,
        return_offsets_mapping=True,
    )

    windows = []
    for i in range(len(encoded["input_ids"])):
        input_ids = encoded["input_ids"][i]
        offsets = encoded["offset_mapping"][i]
        seq_ids = get_seq_ids(encoded, i, tokenizer)

        pad_len = MAX_LEN - len(input_ids)
        if pad_len < 0:
            continue

        attention_mask = [1] * len(input_ids) + [0] * pad_len
        input_ids = input_ids + [PAD_ID] * pad_len

        tt = encoded.get("token_type_ids")
        if tt is not None:
            token_type_ids = tt[i] + [0] * pad_len
        else:
            token_type_ids = [0] * len(input_ids)

        ctx_indices = []
        ctx_offsets = []
        for j, sid in enumerate(seq_ids):
            if sid == 1:
                s, e = offsets[j]
                if s == 0 and e == 0:
                    continue
                ctx_indices.append(j)
                ctx_offsets.append((s, e))

        windows.append(
            {
                "input_ids": input_ids,
                "attention_mask": attention_mask,
                "token_type_ids": token_type_ids,
                "context_indices": ctx_indices,
                "context_offsets": ctx_offsets,
            }
        )

    return windows


@torch.no_grad()
def predict_windows(windows, context, model, device):
    if not windows:
        return postprocess_answer(context[:100]), 0.0, 0

    best_text = None
    best_raw = -1e18
    best_conf = 0.0
    best_start = 0

    for start_i in range(0, len(windows), INFER_BATCH):
        batch = windows[start_i : start_i + INFER_BATCH]

        input_ids = torch.tensor(
            [w["input_ids"] for w in batch], dtype=torch.long, device=device
        )
        attention_mask = torch.tensor(
            [w["attention_mask"] for w in batch], dtype=torch.long, device=device
        )

        kw = {"input_ids": input_ids, "attention_mask": attention_mask}
        if USE_TOKEN_TYPE:
            token_type_ids = torch.tensor(
                [w["token_type_ids"] for w in batch], dtype=torch.long, device=device
            )
            kw["token_type_ids"] = token_type_ids

        with autocast():
            outputs = model(**kw)

        start_logits = outputs.start_logits.float()
        end_logits = outputs.end_logits.float()

        for bi, w in enumerate(batch):
            ctx_idx = w["context_indices"]
            ctx_offsets = w["context_offsets"]
            C = len(ctx_idx)
            if C == 0:
                continue

            st = start_logits[bi][ctx_idx]
            en = end_logits[bi][ctx_idx]

            scores = st[:, None] + en[None, :]
            idxs = torch.arange(C, device=scores.device)
            mask = (idxs[None, :] >= idxs[:, None]) & (
                idxs[None, :] - idxs[:, None] < MAX_ANSWER_LEN
            )
            scores = scores.masked_fill(~mask, -1e9)

            best_flat = int(torch.argmax(scores))
            s_idx = best_flat // C
            e_idx = best_flat % C
            raw_score = float(scores[s_idx, e_idx])

            probs = torch.softmax(scores.view(-1), dim=0)
            conf = float(probs[best_flat])

            s_char, e_char = ctx_offsets[s_idx][0], ctx_offsets[e_idx][1]
            if e_char > s_char:
                text = postprocess_answer(context[s_char:e_char])
                if text and raw_score > best_raw:
                    best_raw = raw_score
                    best_text = text
                    best_conf = conf
                    best_start = s_char

    if best_text is None:
        return postprocess_answer(context[:100]), 0.0, 0

    return best_text, best_conf, best_start


def choose_best(pred_records):
    if not pred_records:
        return ""

    groups = {}
    for pred, weight, conf, start in pred_records:
        key = pred if pred is not None else ""
        if key not in groups:
            groups[key] = [0.0, 0.0, start]
        groups[key][0] += weight
        groups[key][1] += conf
        groups[key][2] = min(groups[key][2], start)

    max_w = max(v[0] for v in groups.values())
    candidates = [(k, v) for k, v in groups.items() if abs(v[0] - max_w) < 1e-12]
    candidates.sort(key=lambda kv: (-kv[1][1], kv[1][2], kv[0]))
    return candidates[0][0]


def loo_model_weight(model_name, idx, lang, val_results, model_scores):
    rows = val_results.get(model_name, [])
    lang_scores = []
    for r in rows:
        if r[0] == idx:
            continue
        if r[4] != lang:
            continue
        lang_scores.append(jaccard_score(r[1], r[2]))

    if lang_scores:
        return safe_mean(lang_scores)

    overall_scores = [jaccard_score(r[1], r[2]) for r in rows if r[0] != idx]
    if overall_scores:
        return safe_mean(overall_scores)

    return model_scores[model_name]["lang"].get(
        lang, model_scores[model_name]["overall"]
    )


def train_eval_fold(
    model_name,
    val_fold,
    train_df,
    win_input,
    win_attn,
    win_tt,
    win_start,
    win_end,
    win_row,
    fold_idx,
    test_windows,
    test_contexts,
    tokenizer,
    device,
):
    train_indices = [i for i, r in enumerate(win_row) if fold_idx[r] != val_fold]
    val_idx = np.where(fold_idx == val_fold)[0]

    try:
        model = AutoModelForQuestionAnswering.from_pretrained(model_name)
    except Exception as e:
        print(f"Failed to load {model_name} on fold {val_fold}: {e}", flush=True)
        return None

    model.to(device)
    ema_model = deepcopy(model)

    dataset = TensorDataset(win_input, win_attn, win_tt, win_start, win_end)
    sampler = SubsetRandomSampler(train_indices)
    loader = DataLoader(
        dataset, batch_size=BATCH_SIZE, sampler=sampler, num_workers=0, pin_memory=True
    )

    lr = LR_BY_MODEL.get(model_name, LR_DEFAULT)
    optimizer = AdamW(model.parameters(), lr=lr, weight_decay=0.01)
    total_steps = max(1, len(loader) * EPOCHS)
    scheduler = get_linear_schedule_with_warmup(
        optimizer,
        num_warmup_steps=int(0.1 * total_steps),
        num_training_steps=total_steps,
    )
    scaler = GradScaler()
    loss_fn = torch.nn.CrossEntropyLoss()

    model.train()
    for epoch in range(EPOCHS):
        for batch in loader:
            optimizer.zero_grad()

            input_ids = batch[0].to(device, non_blocking=True)
            attention_mask = batch[1].to(device, non_blocking=True)
            start_positions = batch[3].to(device, non_blocking=True)
            end_positions = batch[4].to(device, non_blocking=True)

            kw = {"input_ids": input_ids, "attention_mask": attention_mask}
            if USE_TOKEN_TYPE:
                kw["token_type_ids"] = batch[2].to(device, non_blocking=True)

            with autocast():
                outputs = model(**kw)
                loss = (
                    loss_fn(outputs.start_logits, start_positions)
                    + loss_fn(outputs.end_logits, end_positions)
                ) / 2.0

            scaler.scale(loss).backward()
            scaler.unscale_(optimizer)
            torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)
            scaler.step(optimizer)
            scaler.update()
            scheduler.step()

            with torch.no_grad():
                for ema_p, p in zip(ema_model.parameters(), model.parameters()):
                    if p.requires_grad:
                        ema_p.mul_(EMA_DECAY).add_(p.detach(), alpha=1.0 - EMA_DECAY)

    eval_model = ema_model
    eval_model.eval()

    val_predictions = []
    for idx in val_idx:
        row = train_df.iloc[idx]
        context = str(row["context"])
        windows = build_inference_windows(str(row["question"]), context, tokenizer)
        pred, conf, start = predict_windows(windows, context, eval_model, device)
        val_predictions.append(
            (int(idx), str(row["answer_text"]), pred, conf, str(row["language"]), start)
        )

    test_predictions = {}
    for pid, context in test_contexts.items():
        windows = test_windows[pid]
        pred, conf, start = predict_windows(windows, context, eval_model, device)
        test_predictions[pid] = (pred, conf, start)

    del model, ema_model, optimizer, scheduler, scaler, loader, dataset
    gc.collect()
    torch.cuda.empty_cache()

    return val_predictions, test_predictions


def main():
    global PAD_ID, USE_TOKEN_TYPE

    if not torch.cuda.is_available():
        raise RuntimeError("CUDA GPU is required for this task")

    set_seed(SEED)
    device = torch.device("cuda")

    train_df = pd.read_csv("./data/train.csv").reset_index(drop=True)
    test_df = pd.read_csv("./data/test.csv")

    print("Checking available models...", flush=True)
    available_models = []
    for model_name in MODEL_CANDIDATES:
        try:
            model = AutoModelForQuestionAnswering.from_pretrained(model_name)
            del model
            gc.collect()
            torch.cuda.empty_cache()
            available_models.append(model_name)
            print(f"  available: {model_name}", flush=True)
        except Exception as e:
            print(f"  unavailable {model_name}: {e}", flush=True)

    if not available_models:
        raise RuntimeError("No usable pretrained model found")

    try:
        tokenizer = AutoTokenizer.from_pretrained(TOKENIZER_MODEL, use_fast=True)
        config_name = TOKENIZER_MODEL
    except Exception:
        tokenizer = AutoTokenizer.from_pretrained(available_models[0], use_fast=True)
        config_name = available_models[0]

    try:
        config = AutoConfig.from_pretrained(config_name)
    except Exception:
        config = AutoConfig.from_pretrained(available_models[0])

    PAD_ID = tokenizer.pad_token_id
    if PAD_ID is None:
        PAD_ID = tokenizer.eos_token_id
    if PAD_ID is None:
        PAD_ID = tokenizer.unk_token_id
    if PAD_ID is None:
        raise RuntimeError("Could not determine pad token id")

    USE_TOKEN_TYPE = bool(
        getattr(config, "type_vocab_size", 1) and config.type_vocab_size > 1
    )

    print("Preparing training windows...", flush=True)
    train_windows = []
    for row_idx, row in train_df.iterrows():
        for win in build_train_windows(row, tokenizer):
            train_windows.append((row_idx, win))

    if len(train_windows) == 0:
        raise RuntimeError("No training windows were created")

    print(f"Created {len(train_windows)} training windows", flush=True)

    win_row = [w[0] for w in train_windows]
    win_input = torch.tensor([w[1][0] for w in train_windows], dtype=torch.long)
    win_attn = torch.tensor([w[1][1] for w in train_windows], dtype=torch.long)
    win_tt = torch.tensor([w[1][2] for w in train_windows], dtype=torch.long)
    win_start = torch.tensor([w[1][3] for w in train_windows], dtype=torch.long)
    win_end = torch.tensor([w[1][4] for w in train_windows], dtype=torch.long)

    print("Preparing test windows...", flush=True)
    test_contexts = {row["id"]: str(row["context"]) for _, row in test_df.iterrows()}
    test_windows = {}
    for _, row in test_df.iterrows():
        test_windows[row["id"]] = build_inference_windows(
            str(row["question"]), str(row["context"]), tokenizer
        )

    skf = StratifiedKFold(n_splits=5, shuffle=True, random_state=SEED)
    fold_idx = np.zeros(len(train_df), dtype=int)
    for f, (_, val_idx) in enumerate(
        skf.split(np.zeros(len(train_df)), train_df["language"])
    ):
        fold_idx[val_idx] = f

    val_results = {}
    test_results = {}

    for model_name in available_models:
        model_val = []
        model_test = {}
        print(f"Training {model_name}...", flush=True)

        for val_fold in range(5):
            print(f"  Fold {val_fold + 1}/5", flush=True)
            res = train_eval_fold(
                model_name,
                val_fold,
                train_df,
                win_input,
                win_attn,
                win_tt,
                win_start,
                win_end,
                win_row,
                fold_idx,
                test_windows,
                test_contexts,
                tokenizer,
                device,
            )
            if res is None:
                print(f"  Skipping failed fold {val_fold + 1}", flush=True)
                continue

            vp, tp = res
            model_val.extend(vp)
            for pid, pred_conf_start in tp.items():
                model_test[pid] = pred_conf_start

        if model_val:
            model_cv = [jaccard_score(r[1], r[2]) for r in model_val]
            print(
                f"  Model OOF Jaccard: {np.mean(model_cv):.6f} (n={len(model_val)})",
                flush=True,
            )
            val_results[model_name] = model_val
            test_results[model_name] = model_test

        gc.collect()
        torch.cuda.empty_cache()

    model_scores = {}
    for model_name, rows in val_results.items():
        lang_scores = {}
        for lang in ["hindi", "tamil"]:
            lang_rows = [r for r in rows if r[4] == lang]
            lang_scores[lang] = safe_mean(
                [jaccard_score(r[1], r[2]) for r in lang_rows]
            )
        overall = safe_mean([jaccard_score(r[1], r[2]) for r in rows])
        model_scores[model_name] = {"overall": overall, "lang": lang_scores}
        print(
            f"  {model_name}: overall={overall:.6f} "
            f"hindi={lang_scores.get('hindi', 0.0):.6f} "
            f"tamil={lang_scores.get('tamil', 0.0):.6f}",
            flush=True,
        )

    print("Computing weighted OOF ensemble...", flush=True)
    idx_predictions = defaultdict(list)
    for model_name, rows in val_results.items():
        for idx, _, pred, conf, lang, start in rows:
            weight = loo_model_weight(model_name, idx, lang, val_results, model_scores)
            idx_predictions[idx].append((pred, weight, conf, start))

    cv_scores = []
    for idx in range(len(train_df)):
        if idx not in idx_predictions:
            continue
        final_pred = choose_best(idx_predictions[idx])
        cv_scores.append(
            jaccard_score(str(train_df.iloc[idx]["answer_text"]), final_pred)
        )

    overall_cv = np.mean(cv_scores)
    print(
        f"Overall 5-fold OOF Jaccard: {overall_cv:.6f} (n={len(cv_scores)})",
        flush=True,
    )

    print("Building final test predictions...", flush=True)
    test_lang = {row["id"]: row["language"] for _, row in test_df.iterrows()}
    test_groups = defaultdict(list)

    for model_name, model_test in test_results.items():
        for pid, (pred, conf, start) in model_test.items():
            lang = test_lang.get(pid, "")
            weight = model_scores[model_name]["lang"].get(
                lang, model_scores[model_name]["overall"]
            )
            test_groups[pid].append((pred, weight, conf, start))

    final_preds = []
    for pid in test_df["id"]:
        if pid in test_groups:
            pred = choose_best(test_groups[pid])
        else:
            pred = postprocess_answer(test_contexts[pid][:100])

        if not str(pred).strip():
            pred = postprocess_answer(test_contexts[pid][:100])

        final_preds.append(pred)

    submission = pd.DataFrame({"id": test_df["id"], "PredictionString": final_preds})
    submission.to_csv("submission.csv", index=False)
    print("Saved submission.csv", flush=True)


if __name__ == "__main__":
    main()
